const { hunks, resolveConflict, resolveAll, isFullyResolved } = useDiffViewer();

const firstConflict = hunks.find((h) => h.kind === "conflict");
if (firstConflict) resolveConflict(firstConflict.id, "ours");

resolveAll("theirs"); // bulk-resolve every remaining conflict

import {
  DiffViewerRoot, DiffHunkView, useDiffViewer,
} from "@/components/bevelui/diff-viewer";

function Toolbar() {
  const { stats, viewMode, setViewMode } = useDiffViewer();
  return (
    <div className="flex items-center justify-between">
      <span>+{stats.additions} −{stats.deletions}</span>
      <button onClick={() => setViewMode(viewMode === "split" ? "unified" : "split")}>
        Toggle view
      </button>
    </div>
  );
}

function HunkList() {
  const { hunks } = useDiffViewer();
  return <>{hunks.map((h) => <DiffHunkView key={h.id} hunk={h} />)}</>;
}

export function CustomDiff() {
  return (
    <DiffViewerRoot original={a} modified={b}>
      <Toolbar />
      <HunkList />
    </DiffViewerRoot>
  );
}

import { myersDiff, diffLines, buildHunks, computeDiff } from "@/components/bevelui/diff-viewer";

// Generic diff over any token type
const ops = myersDiff(["a", "b", "c"], ["a", "x", "c"]);

// Line-level diff with word spans
const lines = diffLines(originalText, modifiedText);

// Group into hunks with folded context
const hunks = buildHunks(lines, 3);

// Or do both plus stats in one call, matching what DiffViewerRoot uses internally
const { hunks: h2, stats } = computeDiff(originalText, modifiedText, {
  viewMode: "split",
  contextLines: 3,
  wordDiff: true,
  virtualizeThreshold: 500,
});
